// The fields of the grammar ruby, as Node.ChildByFieldID takes them. The
// comment of each one is its name.
const (
	FieldAlias        transit.FieldID = 1  // "alias"
	FieldAlternative  transit.FieldID = 2  // "alternative"
	FieldAlternatives transit.FieldID = 3  // "alternatives"
	FieldArguments    transit.FieldID = 4  // "arguments"
	FieldBegin        transit.FieldID = 5  // "begin"
	FieldBlock        transit.FieldID = 6  // "block"
	FieldBody         transit.FieldID = 7  // "body"
	FieldClass        transit.FieldID = 8  // "class"
	FieldClauses      transit.FieldID = 9  // "clauses"
	FieldCondition    transit.FieldID = 10 // "condition"
	FieldConsequence  transit.FieldID = 11 // "consequence"
	FieldElse         transit.FieldID = 12 // "else"
	FieldEnd          transit.FieldID = 13 // "end"
	FieldExceptions   transit.FieldID = 14 // "exceptions"
	FieldGuard        transit.FieldID = 15 // "guard"
	FieldHandler      transit.FieldID = 16 // "handler"
	FieldKey          transit.FieldID = 17 // "key"
	FieldLeft         transit.FieldID = 18 // "left"
	FieldLocals       transit.FieldID = 19 // "locals"
	FieldMethod       transit.FieldID = 20 // "method"
	FieldName         transit.FieldID = 21 // "name"
	FieldObject       transit.FieldID = 22 // "object"
	FieldOperand      transit.FieldID = 23 // "operand"
	FieldOperator     transit.FieldID = 24 // "operator"
	FieldParameters   transit.FieldID = 25 // "parameters"
	FieldPattern      transit.FieldID = 26 // "pattern"
	FieldReceiver     transit.FieldID = 27 // "receiver"
	FieldRight        transit.FieldID = 28 // "right"
	FieldScope        transit.FieldID = 29 // "scope"
	FieldSuperclass   transit.FieldID = 30 // "superclass"
	FieldValue        transit.FieldID = 31 // "value"
	FieldVariable     transit.FieldID = 32 // "variable"
)

// The short names of the types of the tables.
type (
	action = abi.ParseAction
	header = abi.EntryHeader
	shift  = abi.ShiftAction
	reduce = abi.ReduceAction
)

// The kinds of a parse action.
const (
	typeShift   = abi.ParseActionTypeShift
	typeReduce  = abi.ParseActionTypeReduce
	typeAccept  = abi.ParseActionTypeAccept
	typeRecover = abi.ParseActionTypeRecover
)

